-- Los cuatro pasos nuevos de «Cómo trabajamos» (zquare.uy) en Web → Contenido,
-- en español e inglés: Descubrimiento, Validación, Desarrollo y Puesta en marcha.

update public.contenido_web set es = $j${"titulo": "Descubrimiento", "duracion": "Sin costo", "descripcion": "Nos reunimos para conocer tu idea, entender qué esperás del proyecto y resolver las dudas iniciales. Con eso definimos los próximos pasos, los tiempos y el presupuesto."}$j$, en = $j${"titulo": "Discovery", "duracion": "Free", "descripcion": "We meet to learn about your idea, understand what you expect from the project and answer your first questions. With that we define the next steps, the timeline and the budget."}$j$, publicado = true
  where tipo = 'paso' and orden = 1 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Validación", "duracion": "1–2 semanas", "descripcion": "Transformamos la propuesta en una maqueta que podés probar. Revisamos juntos la experiencia, ajustamos los detalles y confirmamos que estamos yendo en la dirección correcta."}$j$, en = $j${"titulo": "Validation", "duracion": "1–2 weeks", "descripcion": "We turn the proposal into a mockup you can try. We review the experience together, adjust the details and confirm we are heading in the right direction."}$j$, publicado = true
  where tipo = 'paso' and orden = 2 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Desarrollo", "duracion": "Por etapas", "descripcion": "Avanzamos en ciclos de dos semanas, con entregas que podés ver y probar. En cada etapa revisamos los resultados, incorporamos tus comentarios y seguimos construyendo hasta tener todo listo."}$j$, en = $j${"titulo": "Development", "duracion": "In stages", "descripcion": "We work in two-week cycles, with releases you can see and try. At each stage we review the results, take in your feedback and keep building until everything is ready."}$j$, publicado = true
  where tipo = 'paso' and orden = 3 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Puesta en marcha", "duracion": "Al entregar", "descripcion": "Te mostramos cómo funciona todo, capacitamos a tu equipo y acompañamos los primeros días de uso. Resolvemos las dudas que aparezcan para que la transición sea lo más sencilla posible."}$j$, en = $j${"titulo": "Launch", "duracion": "At delivery", "descripcion": "We show you how everything works, train your team and stay with you through the first days of use. We answer any questions that come up so the transition is as smooth as possible."}$j$, publicado = true
  where tipo = 'paso' and orden = 4 and deleted_at is null;
